Given an array of integers and a number k, write a function that returns true if the given array can be divided into pairs such that the sum of every pair is divisible by k.Examples: Input: arr[] = [9, 7, 5, 3], k = 6 Output: True We can divide the array into (9, 3) and (7, 5). Sum of both of these pairs is a multiple of 6.Input: arr[] = [92, 75, 65, 48, 45, 35], k = 10 Output: True We can divide the array into (92, 48), (75, 65) and (45, 35). The sum of all these pairs are multiples of 10.Input: arr[] = [91, 74, 66, 48], k = 10 Output: False Try It YourselfNaive Approach - O(n^2) Time and O(n) SpaceThe idea is to iterate through every element arr[i]. Find if there is another not yet visited element that has a remainder like (k - arr[i]%k). If there is no such element, return false. If a pair is found, then mark both elements as visited. 
            C++

    #include <iostream>
#include <vector>
using namespace std;

bool canPairs(vector<int>& arr, int k) {

    int n = arr.size();

    if (n % 2 == 1)
        return false;

    int count = 0;

    vector<int> vis(n, -1);

    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {

            // If pair is divisible increment the   
            // count and mark elements as visited
            if ((arr[i] + arr[j]) % k == 0 && 
                vis[i] == -1 && vis[j] == -1) {   

                count++;
                vis[i] = 1;
                vis[j] = 1;
            }
        }
    }

    return (count == n / 2);
}

// Driver code
int main() {
    vector<int> arr = {92, 75, 65, 48, 45, 35};
    int k = 10;
    cout << (canPairs(arr, k) ? "True" : "False");
    return 0;
}


