bool canPairs(vector<int> arr, int k) {

    if (arr.size() % 2 != 0)
        return false;

    vector<int> freq(k);

    for (int x : arr) {
        int rem = x % k;

        // If the complement of the current 
        // remainder exists in freq, decrement its count
        if (freq[(k - rem) % k] != 0)
            freq[(k - rem) % k]--;

